<script lang="ts">
  import type { ActionData, PageData } from './$types';
  let { data, form }: { data: PageData; form: ActionData } = $props();
  let source = $state<'zoho' | 'gmail'>('zoho');
  let error = $derived(form && 'error' in form ? form.error : '');
  let folders = $derived(source === 'zoho' ? data.folders : data.gmailFolders);
</script>
<svelte:head><title>Emails · AadOS</title></svelte:head>
<main><header><a href="/">← Inbox</a><div><h1>Emails</h1><p>Turn regular Zoho folders and Gmail labels into focused views.</p></div><a class="settings" href="/settings/emails">Email settings</a></header>
  {#if error}<div class="alert">{error}</div>{/if}
  <section><h2>Add email view</h2><form method="POST" action="?/create" class="grid">
    <label>Provider<select name="source" bind:value={source}><option value="zoho" disabled={!data.connected}>Zoho{data.connected ? '' : ' — connect first'}</option><option value="gmail" disabled={!data.gmailConnected}>Gmail{data.gmailConnected ? '' : ' — connect first'}</option></select></label>
    <label>Folder or label<select name="folderId" required><option value="">Choose one</option>{#each folders as folder}<option value={folder.id}>{folder.path || folder.name}</option>{/each}</select></label>
    <label>View<select name="parser" required><option value="shop">Shopping</option><option value="health">Health</option></select></label>
    <label>Name<input name="name" placeholder="Use Shopping or Health" /></label><button disabled={folders.length === 0}>Add view</button>
  </form></section>
  <section><h2>Email views</h2>{#if data.pipelines.length === 0}<p class="muted">Choose a folder for Shopping or Health.</p>{/if}<div class="views">{#each data.pipelines as workflow}<article><div class="icon">{workflow.parser === 'shop' ? '🛍' : workflow.parser === 'health' ? '♡' : '✉'}</div><div><small>{workflow.source === 'gmail' ? 'Gmail label' : 'Zoho folder'} · {workflow.folderName}</small><h3><a href={`/pipelines/${workflow.id}`}>{workflow.name}</a></h3><p>{data.itemCounts[workflow.id] || 0} items · {workflow.enabled ? 'hourly sync' : 'paused'}{workflow.lastError ? ` · ${workflow.lastError}` : ''}</p></div><div class="actions"><form method="POST" action="?/sync"><input type="hidden" name="id" value={workflow.id}><button>Sync now</button></form><form method="POST" action="?/toggle"><input type="hidden" name="id" value={workflow.id}><button>{workflow.enabled ? 'Pause' : 'Enable'}</button></form></div></article>{/each}</div></section>
</main>
<style>main{max-width:980px;margin:auto;padding:32px;color:#29344c}header{display:flex;gap:24px;align-items:flex-start;margin-bottom:24px}header>a{color:#3157de;text-decoration:none;margin-top:7px}header div{flex:1}h1{margin:0}header p,.muted{color:#8994a8}.settings{white-space:nowrap}section{background:#fff;border:1px solid #e4e9f2;border-radius:14px;padding:20px;margin:16px 0}h2{font-size:14px;text-transform:uppercase;letter-spacing:.08em;margin:0 0 16px;color:#68758e}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}label{display:grid;gap:6px;font-size:11px;font-weight:750;color:#647087}input,select{width:100%;border:1px solid #dbe1eb;border-radius:8px;padding:10px;background:#fbfcfe}button{border:1px solid #d9dfeb;background:#fff;border-radius:8px;padding:9px 13px;color:#43516c}.grid>button{align-self:end}.views{display:grid;gap:10px}.views article{display:grid;grid-template-columns:38px 1fr auto;gap:13px;align-items:center;border:1px solid #e7ebf2;border-radius:10px;padding:13px}.icon{font-size:22px}.views h3{margin:3px 0}.views a{color:#304fbe;text-decoration:none}.views p,.views small{margin:0;color:#8a95a8;font-size:11px}.actions{display:flex;gap:8px}.actions form{margin:0}.alert{padding:11px 14px;border-radius:9px;background:#fff0f1;color:#a5414d}@media(max-width:650px){.grid{grid-template-columns:1fr}header{display:block}.settings{display:inline-block;margin-top:8px}.views article{grid-template-columns:30px 1fr}.actions{grid-column:2;flex-wrap:wrap}}</style>
